def test_weekly_continues_only_unattempted_cases_after_a_guard_stop(tmp_path, monkeypatch):
    import slow_weekly
    attempts = []

    def run_suite(**kwargs):
        nodes = kwargs['selectors']
        attempts.append(nodes[:])
        if len(attempts) == 1:
            return dict(workers=[dict(selected=nodes[:1], completed=[])],
                        exit_code=137, reason='memory')
        return dict(workers=[dict(selected=nodes, completed=nodes)],
                    exit_code=0, reason='exit')

    monkeypatch.setattr(slow_weekly.bounded, 'run_suite', run_suite)
    segments, attempted = slow_weekly.run_tier(
        tmp_path, ['a', 'b', 'c'], tmp_path/'ordinary', 8)
    assert attempts == [['a', 'b', 'c'], ['b', 'c']]
    assert attempted == {'a', 'b', 'c'}
    assert segments[0][1]['exit_code'] == 137

def test_lower_total_explore_cannot_win_with_worse_reconstruction():
    from SentenceCompose import sentence_pair
    active = torch.tensor([True, True, True])
    r = [torch.tensor([1., 2., 3.]), torch.tensor([2., 1., 3.])]
    def compose(cache, prior):
        return torch.zeros(3) if prior is None else torch.ones(3)
    def score(path, alternative):
        return torch.full((3,), 1. if alternative else 2.), path
    chosen, _, wins = sentence_pair(None, compose, score, lambda loss: None,
        active=active, reconstruction=lambda state: r[int(state[0])])
    assert wins.tolist() == [False, True, True]
    assert chosen.tolist() == [0., 1., 1.]
